<script setup lang="ts">import { drawerResizeHandleClassName } from '@fex-design/styles/drawer'; import { cn } from '@fex/utils'; import { useDrawerContext } from './context'; const props = defineProps<{ class?: string }>(); const context = useDrawerContext('DrawerResizeHandle'); const edge = { left:'right', right:'left', top:'bottom', bottom:'top' }[context.placement.value ?? 'right'] as any;</script><template><div v-if="context.resize" v-bind="context.resize.getHandleProps(edge)" data-slot="drawer-resize-handle" :data-edge="edge" :class="cn(drawerResizeHandleClassName, props.class)" /></template>
